@mixfix(pattern: "{person: Person} works at {company: Company}")
def worksAt() =>
    return Association(left: person, right: company, relation: "works_at", strength: 3.421)
end
def main() =>
    return Person(name: "Ada") works at Company(name: "Felidae")
end
